<div class="page-head"><div><span class="eyebrow dark"><?= e(tr('مشترکان شبکه','Network subscribers')) ?></span><h1><?= e(tr('کاربران User Manager','User Manager users')) ?></h1><p><?= fa_digits($total) ?> <?= e(tr('کاربر یافت شد','users found')) ?></p></div><?php if(Auth::canWrite()):?><a class="button primary" href="<?= e(url('user-form')) ?>">＋ <?= e(tr('کاربر جدید','New user')) ?></a><?php endif;?></div>
<form method="get" class="filter-bar"><input type="hidden" name="r" value="users"><label class="search-box"><span>⌕</span><input name="q" value="<?= e($search) ?>" placeholder="<?= e(tr('نام کاربری، نام یا تلفن...','Username, name or phone...')) ?>"></label><select name="status"><option value=""><?= e(tr('همه وضعیت‌ها','All statuses')) ?></option><?php foreach(['active','disabled','expired','suspended','missing_on_device','needs_plan_assignment'] as $s):?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(status_text($s)) ?></option><?php endforeach;?></select><select name="router"><option value="0"><?= e(tr('همه روترها','All routers')) ?></option><?php foreach($routers as $r):?><option value="<?= e($r['id']) ?>" <?= $routerId===(int)$r['id']?'selected':'' ?>><?= e($r['name']) ?></option><?php endforeach;?></select><button class="button ghost"><?= e(tr('فیلتر','Filter')) ?></button><?php if($search!==''||$status!==''||$routerId):?><a class="button text" href="<?= e(url('users')) ?>"><?= e(tr('پاک‌کردن','Clear')) ?></a><?php endif;?></form>
<section class="panel"><div class="table-wrap"><table><thead><tr><th><?= e(tr('کاربر','User')) ?></th><th><?= e(tr('اتصال','Connection')) ?></th><th><?= e(tr('وضعیت','Status')) ?></th><th><?= e(tr('پلن','Plan')) ?></th><th><?= e(tr('سرعت','Rate')) ?></th><th><?= e(tr('انقضا','Expires')) ?></th><th></th></tr></thead><tbody>
<?php foreach($users as $user):?><tr><td><a class="user-cell" href="<?= e(url('user-detail',['id'=>$user['id']])) ?>"><span class="avatar small-avatar"><?= e(mb_strtoupper(mb_substr($user['username'],0,1))) ?></span><span><strong dir="ltr"><?= e($user['username']) ?></strong><small><?= e($user['full_name']?:$user['phone']) ?></small></span></a></td><td><span class="online-indicator <?= $user['is_online']?'on':'off' ?>"></span><?= e($user['is_online']?tr('آنلاین','Online'):tr('آفلاین','Offline')) ?><small class="table-sub"><?= e($user['router_name']) ?></small></td><td><span class="badge <?= badge_class($user['status']) ?>"><?= e(status_text($user['status'])) ?></span></td><td><?= e($user['plan_name']?:'—') ?></td><td dir="ltr"><?= e($user['rate_limit']?:'—') ?></td><td><span class="<?= $user['expiration_date']&&$user['expiration_date']<date('Y-m-d')?'danger-text':'' ?>"><?= e($user['expiration_date']?:'—') ?></span></td><td><a class="button ghost small" href="<?= e(url('user-detail',['id'=>$user['id']])) ?>"><?= e(tr('مشاهده','View')) ?></a></td></tr><?php endforeach;?>
<?php if(!$users):?><tr><td colspan="7" class="empty"><?= e(tr('کاربری با این فیلتر پیدا نشد.','No users match these filters.')) ?></td></tr><?php endif;?></tbody></table></div>
<?php $pages=(int)ceil($total/$perPage);if($pages>1):?><nav class="pagination"><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?= $i===$page?'active':'' ?>" href="<?= e(url('users',['page'=>$i,'q'=>$search,'status'=>$status,'router'=>$routerId])) ?>"><?= fa_digits($i) ?></a><?php endfor;?></nav><?php endif;?></section>
